#include "projected_base.hpp"
int main(int argc,char**argv){Kokkos::ScopeGuard guard(argc,argv);try{Audit a(16,2.2,1e-4);std::cout<<"{\"points\":"<<a.cells.size()<<"}\n"<<std::flush;std::vector<double>v(20*a.cells.size()),out(7*a.cells.size());char mode;while(std::cin.read(&mode,1)){double pars[2];if(!std::cin.read(reinterpret_cast<char*>(pars),16)||!std::cin.read(reinterpret_cast<char*>(v.data()),v.size()*8))throw std::runtime_error("truncated input");if(mode=='d'||mode=='c')a.Constraints(v.data(),out.data(),pars[0],mode=='d');else if(mode=='e')a.Norms(v.data(),out.data());else throw std::runtime_error("unknown mode");std::cout.write(reinterpret_cast<char*>(out.data()),a.cells.size()*(mode=='e'?2:7)*8);std::cout.flush();}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
